package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	users = make(map[string]User)
	mutex sync.RWMutex
)

// GetAllUsers returns all users
func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()
	var list []User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user
func CreateUser(name, email string) User {
	mutex.Lock()
	defer mutex.Unlock()

	u := User{
		ID:    uuid.New().String(),
		Name:  name,
		Email: email,
	}
	users[u.ID] = u
	return u
}

// GetUserByID returns a user by ID
func GetUserByID(id string) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	u, ok := users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"rep-3/internal/service"
)

// GetUsers handles the GET request for all users
func GetUsers(w http.ResponseWriter, r *http.Request) {
	list := service.GetAllUsers()
	json.NewEncoder(w).Encode(list)
}

// CreateUser handles the POST request to create a new user
func CreateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name  string `json:"name"`
		Email string `json:"email"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	u := service.CreateUser(req.Name, req.Email)
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(u)
}

// GetUser handles the GET request for a single user by ID
func GetUser(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	u, ok := service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"rep-3/internal/api"
)

func main() {
	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.GetUsers(w, r)
		case http.MethodPost:
			api.CreateUser(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/users/", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.GetUser(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"testing"
)

func TestGetAllUsers(t *testing.T) {
	// Clear users before test
	users = make(map[string]User)

	user1 := CreateUser("Alice", "alice@example.com")
	user2 := CreateUser("Bob", "bob@example.com")

	allUsers := GetAllUsers()

	if len(allUsers) != 2 {
		t.Errorf("Expected 2 users, got %d", len(allUsers))
	}

	found1 := false
	found2 := false
	for _, u := range allUsers {
		if u.ID == user1.ID && u.Name == user1.Name && u.Email == user1.Email {
			found1 = true
		}
		if u.ID == user2.ID && u.Name == user2.Name && u.Email == user2.Email {
			found2 = true
		}
	}

	if !found1 || !found2 {
		t.Errorf("Did not find all created users in the list")
	}
}

func TestCreateUser(t *testing.T) {
	// Clear users before test
	users = make(map[string]User)

	name := "Charlie"
	email := "charlie@example.com"

	u := CreateUser(name, email)

	if u.Name != name {
		t.Errorf("Expected user name %s, got %s", name, u.Name)
	}
	if u.Email != email {
		t.Errorf("Expected user email %s, got %s", email, u.Email)
	}

	if _, ok := users[u.ID]; !ok {
		t.Errorf("User not found in map after creation")
	}
}

func TestGetUserByID(t *testing.T) {
	// Clear users before test
	users = make(map[string]User)

	user1 := CreateUser("David", "david@example.com")

	foundUser, ok := GetUserByID(user1.ID)

	if !ok {
		t.Errorf("Expected to find user with ID %s", user1.ID)
	}

	if foundUser.ID != user1.ID || foundUser.Name != user1.Name || foundUser.Email != user1.Email {
		t.Errorf("Found user mismatch. Expected %+v, got %+v", user1, foundUser)
	}

	_, ok = GetUserByID("nonexistent-id")
	if ok {
		t.Errorf("Expected not to find a user with a nonexistent ID")
	}
}

package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"rep-3/internal/service"
)

func TestGetUsers(t *testing.T) {
	// Clear users and add some test data
	service.ClearUsers()
	service.CreateUser("Alice", "alice@example.com")
	service.CreateUser("Bob", "bob@example.com")

	req, _ := http.NewRequest("GET", "/users", nil)
	rr := httptest.NewRecorder()

	GetUsers(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
	}

	var users []service.User
	json.NewDecoder(rr.Body).Decode(&users)

	if len(users) != 2 {
		t.Errorf("handler returned unexpected number of users: got %v want %v", len(users), 2)
	}
}

func TestCreateUser(t *testing.T) {
	// Clear users before test
	service.ClearUsers()

	var jsonStr = []byte(`{"name":"Charlie","email":"charlie@example.com"}`)
	req, _ := http.NewRequest("POST", "/users", bytes.NewBuffer(jsonStr))
	req.Header.Set("Content-Type", "application/json")
	rr := httptest.NewRecorder()

	CreateUser(rr, req)

	if status := rr.Code; status != http.StatusCreated {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusCreated)
	}

	var user service.User
	json.NewDecoder(rr.Body).Decode(&user)

	if user.Name != "Charlie" || user.Email != "charlie@example.com" {
		t.Errorf("handler returned unexpected user: %+v", user)
	}

	if _, ok := service.GetUserByID(user.ID); !ok {
		t.Errorf("User not found in service after creation via handler")
	}
}

func TestGetUser(t *testing.T) {
	// Clear users and add a test user
	service.ClearUsers()
	user := service.CreateUser("David", "david@example.com")

	req, _ := http.NewRequest("GET", "/users/"+user.ID, nil)
	rr := httptest.NewRecorder()

	GetUser(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v", status, http.StatusOK)
	}

	var foundUser service.User
	json.NewDecoder(rr.Body).Decode(&foundUser)

	if foundUser.ID != user.ID || foundUser.Name != user.Name || foundUser.Email != user.Email {
		t.Errorf("Found user mismatch. Expected %+v, got %+v", user, foundUser)
	}

	// Test for non-existent user
	req, _ = http.NewRequest("GET", "/users/nonexistent-id", nil)
	rr = httptest.NewRecorder()
	GetUser(rr, req)

	if status := rr.Code; status != http.StatusNotFound {
		t.Errorf("handler returned wrong status code for nonexistent user: got %v want %v", status, http.StatusNotFound)
	}
}

